// ═══════════════════════════════════════════════════════════
// [1] Prepare + Guard v2 — يدعم الآن الصفحات الممسوحة (Vision)
// ═══════════════════════════════════════════════════════════
const body = $input.first().json.body || $input.first().json;
const text = body.text || '';
const company = (body.company || '').trim();
const period = (body.period || '').trim();
const scannedImages = Array.isArray(body.scanned_images) ? body.scanned_images : [];

if (!company || !period) {
  throw new Error('بيانات ناقصة: يجب إرسال اسم الشركة والفترة.');
}

const hasImages = scannedImages.length > 0;

// لو ما في نص لكن في صور → نكمل (Vision سيعوض)
if (!text && !hasImages) {
  throw new Error('لم يتم إرسال أي بيانات.');
}

let clean = (text || '').replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
clean = clean.replace(/([\u0600-\u06FF])[a-zA-Z%&$#@*]+([\u0600-\u06FF])/g, '$1$2');
clean = clean.replace(/[ \t]+/g, ' ');
clean = clean.replace(/\n{3,}/g, '\n\n');
clean = clean.trim();

// Guard النص فقط إذا ما في صور
if (!hasImages) {
  if (clean.length < 400) {
    throw new Error('تعذّر قراءة محتوى كافٍ من الملف. قد يكون الملف صورة ممسوحة لا تحتوي نصًا. الرجاء رفع PDF نصّي.');
  }
  const digitCount = (clean.match(/[0-9٠-٩]/g) || []).length;
  if (digitCount < 30) {
    throw new Error('الملف لا يبدو قائمة مالية. تأكد من رفع القائمة المالية الصحيحة.');
  }
}

const HARD_LIMIT = 70000;
let truncated = false;
if (clean.length > HARD_LIMIT) {
  clean = clean.substring(0, HARD_LIMIT);
  truncated = true;
}

const digitCount = (clean.match(/[0-9٠-٩]/g) || []).length;

return [{
  json: {
    company,
    period,
    clean_text: clean,
    scanned_images: scannedImages,
    has_vision: hasImages,
    meta: {
      original_length: text.length,
      clean_length: clean.length,
      digit_count: digitCount,
      truncated,
      scanned_pages: scannedImages.length
    }
  }
}];

// ═══════════════════════════════════════════════════════════
// [2] Build Extract Request v3 — يدعم Vision + إصلاح الربح التشغيلي
// ═══════════════════════════════════════════════════════════
const inp = $input.first().json;
const { company, period, clean_text, scanned_images, has_vision } = inp;

const instructions =
'أنت مُستخرِج بيانات مالية متخصص في القوائم المالية السعودية. مهمتك الوحيدة: استخراج الأرقام الخام كما وردت.\n\n' +
'قواعد مُلزمة:\n' +
'1- انقل كل رقم كما هو. لا تحسب، لا تجمع، لا تطرح.\n' +
'2- إذا لم تجد بندًا، ضع null. ممنوع التخمين.\n' +
'3- إجمالي الربح (Gross) ≠ الربح التشغيلي (Operating) ≠ صافي الربح (Net). هذه ثلاثة أرقام مختلفة تمامًا.\n' +
'3b- الربح التشغيلي يُؤخذ حرفيًا من السطر المسمى "الربح التشغيلي" أو "Operating Profit" في القائمة. ممنوع حسابه بالطرح أو الجمع من أرقام أخرى.\n' +
'3c- لشركات الاتصالات: الربح التشغيلي يظهر بعد خصم جميع المصاريف التشغيلية (بيعية + إدارية + استهلاك + إطفاء + برنامج تقاعد مبكر). خذه من السطر الصريح فقط.\n' +
'3d- جوهري: لا تخلط صافي الربح قبل الزكاة بـ operating_profit. هما رقمان مختلفان تمامًا.\n' +
'4- تكلفة الإيرادات تُؤخذ من قائمة الدخل الرئيسية فقط، مباشرة قبل إجمالي الربح.\n' +
'5- سجّل الوحدة كما وردت.\n' +
'6- إذا وُجد عمودان، انقل القيمتين في current و previous.\n' +
'7- ممنوع أي نص وصفي أو نسب محسوبة.\n' +
'8- رأس المال والأرباح المبقاة من قائمة المركز المالي أو حقوق الملكية.\n' +
'9- التدفقات النقدية: خذ كل من التشغيلي والاستثماري والتمويلي من قائمة التدفقات النقدية مباشرة. الأرقام السالبة تُسجَّل بإشارة سالبة.\n\n' +
'مصطلحات البنوك:\n' +
'- "صافي دخل التمويل" أو "إيرادات التمويل" = revenue\n' +
'- "مخصص خسائر الائتمان" = cost_of_revenue\n' +
'- "إجمالي دخل التشغيل" = gross_profit\n' +
'- "صافي الدخل" أو "ربح الفترة" = net_profit\n' +
'- "إجمالي الموجودات" = total_assets\n' +
'- "إجمالي المطلوبات" = total_liabilities\n' +
'- "إجمالي حقوق المساهمين" = total_equity\n' +
'- "النقد وما في حكمه" = cash_and_equivalents\n\n' +
'مصطلحات الشركات العادية:\n' +
'- "الإيرادات" أو "المبيعات" = revenue\n' +
'- "تكلفة الإيرادات" = cost_of_revenue\n' +
'- "إجمالي الربح" = gross_profit\n\n' +
'مصطلحات الاتصالات:\n' +
'- "تكلفة العمليات التشغيلية" = cost_of_revenue\n' +
'- "إجمالي الربح" = gross_profit (بعد خصم تكلفة الإيرادات فقط)\n' +
'- "الربح التشغيلي" = operating_profit (بعد خصم جميع المصاريف التشغيلية)\n' +
'- "صافي الربح قبل الزكاة" ≠ operating_profit\n\n' +
'القائمة المالية لشركة ' + company + ' — فترة ' + period + ':\n' +
(clean_text || '(النص غير متاح — استخرج من الصور أعلاه)') +
'\n\nأرجع JSON بهذا الشكل بالضبط:\n' +
'{"currency":"SAR","unit":"ألف ريال","unit_multiplier":1000,' +
'"income_statement":{"revenue":{"current":null,"previous":null},"cost_of_revenue":{"current":null,"previous":null},"gross_profit":{"current":null,"previous":null},"operating_expenses":{"current":null,"previous":null},"operating_profit":{"current":null,"previous":null},"depreciation_amortization":{"current":null,"previous":null},"finance_costs":{"current":null,"previous":null},"zakat_tax":{"current":null,"previous":null},"net_profit":{"current":null,"previous":null}},' +
'"balance_sheet":{"current_assets":{"current":null,"previous":null},"non_current_assets":{"current":null,"previous":null},"total_assets":{"current":null,"previous":null},"current_liabilities":{"current":null,"previous":null},"non_current_liabilities":{"current":null,"previous":null},"total_liabilities":{"current":null,"previous":null},"total_equity":{"current":null,"previous":null},"share_capital":{"current":null,"previous":null},"retained_earnings":{"current":null,"previous":null},"inventory":{"current":null,"previous":null},"cash_and_equivalents":{"current":null,"previous":null}},' +
'"cash_flow":{"operating_cash_flow":{"current":null,"previous":null},"investing_cash_flow":{"current":null,"previous":null},"financing_cash_flow":{"current":null,"previous":null},"capex":{"current":null,"previous":null}},' +
'"segments":[{"label":"اسم القطاع","value":null}]}';

// بناء محتوى الرسالة — نصوص + صور إذا وجدت
const userContent = [];

if (has_vision && Array.isArray(scanned_images) && scanned_images.length > 0) {
  userContent.push({
    type: 'text',
    text: `القوائم المالية لشركة ${company} — فترة ${period}\nالصور التالية هي صفحات ممسوحة ضوئياً من القائمة المالية، استخرج منها الأرقام:`
  });
  for (const img of scanned_images.slice(0, 6)) {
    userContent.push({
      type: 'image',
      source: { type: 'base64', media_type: img.media_type || 'image/jpeg', data: img.data }
    });
  }
  userContent.push({ type: 'text', text: instructions });
} else {
  userContent.push({ type: 'text', text: instructions });
}

const apiBody = {
  model: 'claude-sonnet-4-5-20250929',
  max_tokens: 3000,
  temperature: 0,
  messages: [
    { role: 'user', content: userContent },
    { role: 'assistant', content: '{' }
  ]
};

return [{
  json: {
    company,
    period,
    meta: inp.meta,
    has_vision: has_vision || false,
    api_body: JSON.stringify(apiBody)
  }
}];

// [3] Parse + Validate v2 — يستخدم الاستخراج البرمجي أولاً
const ai = $input.first().json;
const meta = ai.meta || {};
const buildNode = $('Build Extract Request').first().json;
const codeNode = $('Code in JavaScript').first().json;
const company = buildNode.company;
const period = buildNode.period;

function num(x) {
  if (x === null || x === undefined || x === '') return null;
  if (typeof x === 'number') return isFinite(x) ? x : null;
  const n = parseFloat(String(x).replace(/[,٬\s]/g, '').replace(/[()]/g, m => m === '(' ? '-' : ''));
  return isFinite(n) ? n : null;
}
function pFP(o) {
  if (!o) return { current: null, previous: null };
  return { current: num(o.current), previous: num(o.previous) };
}

const prog = codeNode && codeNode.programmatic_extraction;
const isRel = prog && prog.is_reliable;
let F, source;

if (isRel) {
  source = 'programmatic';
  const d = prog.data;
  F = {
    revenue:            pFP(d.revenue),
    cost_of_revenue:    pFP(d.cost_of_revenue),
    gross_profit:       pFP(d.gross_profit),
    operating_expenses: { current: null, previous: null },
    operating_profit:   pFP(d.operating_profit),
    depreciation:       { current: null, previous: null },
    finance_costs:      { current: null, previous: null },
    zakat_tax:          { current: null, previous: null },
    net_profit:         pFP(d.net_profit),
    current_assets:     pFP(d.current_assets),
    non_current_assets: { current: null, previous: null },
    total_assets:       pFP(d.total_assets),
    current_liabilities:pFP(d.current_liabilities),
    non_current_liab:   { current: null, previous: null },
    total_liabilities:  pFP(d.total_liabilities),
    total_equity:       pFP(d.total_equity),
    share_capital:      pFP(d.share_capital),
    retained_earnings:  pFP(d.retained_earnings),
    inventory:          { current: null, previous: null },
    cash:               pFP(d.cash),
    operating_cf:       pFP(d.operating_cf),
    investing_cf:       pFP(d.investing_cf),
    financing_cf:       pFP(d.financing_cf),
    capex:              { current: null, previous: null }
  };
} else {
  source = 'ai';
  if (!ai.content || !Array.isArray(ai.content)) throw new Error('رد غير متوقع.');
  let txt = ai.content.filter(b => b && b.type === 'text').map(b => b.text || '').join('');
  if (!txt.trim().startsWith('{')) txt = '{' + txt;
  txt = txt.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  let raw;
  try { raw = JSON.parse(txt); } catch(e) {
    const en = txt.lastIndexOf('}');
    if (en > 0) { try { raw = JSON.parse(txt.slice(0, en+1)); } catch(e2) {} }
    if (!raw) throw new Error('JSON غير صالح.');
  }
  function pick(obj, path) {
    const parts = path.split('.');
    let o = obj;
    for (const p of parts) { if (o == null) return null; o = o[p]; }
    return o;
  }
  function pair(path) {
    const o = pick(raw, path) || {};
    return { current: num(o.current), previous: num(o.previous) };
  }
  F = {
    revenue:            pair('income_statement.revenue'),
    cost_of_revenue:    pair('income_statement.cost_of_revenue'),
    gross_profit:       pair('income_statement.gross_profit'),
    operating_expenses: pair('income_statement.operating_expenses'),
    operating_profit:   pair('income_statement.operating_profit'),
    depreciation:       pair('income_statement.depreciation_amortization'),
    finance_costs:      pair('income_statement.finance_costs'),
    zakat_tax:          pair('income_statement.zakat_tax'),
    net_profit:         pair('income_statement.net_profit'),
    current_assets:     pair('balance_sheet.current_assets'),
    non_current_assets: pair('balance_sheet.non_current_assets'),
    total_assets:       pair('balance_sheet.total_assets'),
    current_liabilities:pair('balance_sheet.current_liabilities'),
    non_current_liab:   pair('balance_sheet.non_current_liabilities'),
    total_liabilities:  pair('balance_sheet.total_liabilities'),
    total_equity:       pair('balance_sheet.total_equity'),
    share_capital:      pair('balance_sheet.share_capital'),
    retained_earnings:  pair('balance_sheet.retained_earnings'),
    inventory:          pair('balance_sheet.inventory'),
    cash:               pair('balance_sheet.cash_and_equivalents'),
    operating_cf:       pair('cash_flow.operating_cash_flow'),
    investing_cf:       pair('cash_flow.investing_cash_flow'),
    financing_cf:       pair('cash_flow.financing_cash_flow'),
    capex:              pair('cash_flow.capex')
  };
}

const checks = [], TOL = 0.02;
function relErr(a, b) {
  if (a == null || b == null) return null;
  return Math.abs(a-b) / Math.max(Math.abs(a), Math.abs(b), 1);
}
function checkEq(name, lhs, rhs, side) {
  const e = relErr(lhs, rhs);
  if (e === null) { checks.push({name, status: 'skip'}); return; }
  if (e <= TOL) checks.push({name, status: 'pass', error_pct: +(e*100).toFixed(2)});
  else checks.push({name, status: 'fail', error_pct: +(e*100).toFixed(2), side});
}

for (const side of ['current', 'previous']) {
  const ta = F.total_assets[side], tl = F.total_liabilities[side], te = F.total_equity[side];
  if (ta != null && tl != null && te != null) checkEq('معادلة الميزانية (' + side + ')', ta, tl + te, side);
  if (F.gross_profit[side] != null && F.revenue[side] != null && F.cost_of_revenue[side] != null)
    checkEq('إجمالي الربح (' + side + ')', F.gross_profit[side], F.revenue[side] - Math.abs(F.cost_of_revenue[side]), side);
}

const failed = checks.filter(c => c.status === 'fail');
const passed = checks.filter(c => c.status === 'pass');
const hasCore = F.revenue.current != null || F.net_profit.current != null || F.total_assets.current != null;
let confidence = 'high';
const warnings = [];
if (!hasCore) { confidence = 'low'; warnings.push('لم يُعثر على البنود الأساسية.'); }
if (failed.length > 0) {
  confidence = failed.length >= 2 ? 'low' : 'medium';
  failed.forEach(c => warnings.push('فشل تحقق: ' + c.name));
}
if (source === 'ai') warnings.push('تم الاستخراج بواسطة AI — الاستخراج البرمجي لم يكن كافياً.');
if (meta.truncated) { if (confidence === 'high') confidence = 'medium'; warnings.push('تم اقتطاع جزء من النص.'); }

return [{json:{company, period, currency:'SAR', unit_text:'ألف ريال', unit_multiplier:1000, extraction_source:source, figures:F, segments:[], validation:{checks, passed:passed.length, failed:failed.length, confidence, warnings}, meta}}];

// ═══════════════════════════════════════════════════════════
// [4] Compute — حساب كل النسب والتغيّرات برمجيًا (v17)
// أضيف: cashflow_summary, equity_summary, نسب مديونية إضافية
// ═══════════════════════════════════════════════════════════
const inp = $input.first().json;
const F = inp.figures;
const mult = inp.unit_multiplier || 1;

const r2 = (n, d = 2) => (n == null || !isFinite(n)) ? null : +n.toFixed(d);
function ratio(a, b) {
  if (a == null || b == null || b === 0) return null;
  return a / b;
}
function pct(a, b) {
  const x = ratio(a, b);
  return x == null ? null : r2(x * 100);
}
function change(cur, prev) {
  if (cur == null || prev == null || prev === 0) return null;
  return r2(((cur - prev) / Math.abs(prev)) * 100);
}
function trendOf(ch) {
  if (ch == null) return 'flat';
  if (ch > 0.05) return 'up';
  if (ch < -0.05) return 'down';
  return 'flat';
}
const cur = k => F[k] ? F[k].current : null;
const prv = k => F[k] ? F[k].previous : null;

const toBillion = v => v == null ? null : r2((v * mult) / 1e9, 2);

const ratios = [];
function addRatio(label, valuePct, prevPct, formula) {
  if (valuePct == null) return;
  ratios.push({
    label,
    value: valuePct + '%',
    previous: prevPct != null ? prevPct + '%' : null,
    value_raw: valuePct,
    previous_raw: prevPct,
    source: 'محسوب برمجيًا: ' + formula
  });
}

addRatio('هامش صافي الربح', pct(cur('net_profit'), cur('revenue')), pct(prv('net_profit'), prv('revenue')), 'صافي الربح ÷ الإيرادات');
addRatio('هامش إجمالي الربح', pct(cur('gross_profit'), cur('revenue')), pct(prv('gross_profit'), prv('revenue')), 'إجمالي الربح ÷ الإيرادات');
addRatio('هامش الربح التشغيلي', pct(cur('operating_profit'), cur('revenue')), pct(prv('operating_profit'), prv('revenue')), 'الربح التشغيلي ÷ الإيرادات');

const currentRatioCur = ratio(cur('current_assets'), cur('current_liabilities'));
const currentRatioPrv = ratio(prv('current_assets'), prv('current_liabilities'));
if (currentRatioCur != null) ratios.push({ label: 'نسبة التداول', value: r2(currentRatioCur) + 'x', previous: currentRatioPrv != null ? r2(currentRatioPrv) + 'x' : null, value_raw: r2(currentRatioCur), source: 'محسوب برمجيًا: الأصول المتداولة ÷ الخصوم المتداولة' });

const quickCur = ratio((cur('current_assets') != null && cur('inventory') != null) ? cur('current_assets') - cur('inventory') : null, cur('current_liabilities'));
if (quickCur != null) ratios.push({ label: 'النسبة السريعة', value: r2(quickCur) + 'x', previous: null, value_raw: r2(quickCur), source: 'محسوب برمجيًا: (المتداولة − المخزون) ÷ الخصوم المتداولة' });

// --- نسب المديونية (موسّعة v17) ---
const deCur = ratio(cur('total_liabilities'), cur('total_equity'));
if (deCur != null) ratios.push({ label: 'نسبة الدين إلى حقوق الملكية', value: r2(deCur) + 'x', previous: null, value_raw: r2(deCur), source: 'محسوب برمجيًا: إجمالي الخصوم ÷ حقوق الملكية' });

const daCur = pct(cur('total_liabilities'), cur('total_assets'));
if (daCur != null) ratios.push({ label: 'نسبة الدين إلى الأصول', value: daCur + '%', previous: pct(prv('total_liabilities'), prv('total_assets')) != null ? pct(prv('total_liabilities'), prv('total_assets')) + '%' : null, value_raw: daCur, source: 'محسوب برمجيًا: إجمالي الخصوم ÷ إجمالي الأصول' });

const eqMultiplierCur = ratio(cur('total_assets'), cur('total_equity'));
if (eqMultiplierCur != null) ratios.push({ label: 'مضاعف حقوق الملكية', value: r2(eqMultiplierCur) + 'x', previous: null, value_raw: r2(eqMultiplierCur), source: 'محسوب برمجيًا: إجمالي الأصول ÷ حقوق الملكية' });

const roeCur = pct(cur('net_profit'), cur('total_equity'));
if (roeCur != null) ratios.push({ label: 'العائد على حقوق الملكية (ROE)', value: roeCur + '%', previous: pct(prv('net_profit'), prv('total_equity')) != null ? pct(prv('net_profit'), prv('total_equity')) + '%' : null, value_raw: roeCur, source: 'محسوب برمجيًا: صافي الربح ÷ حقوق الملكية' });
const roaCur = pct(cur('net_profit'), cur('total_assets'));
if (roaCur != null) ratios.push({ label: 'العائد على الأصول (ROA)', value: roaCur + '%', previous: null, value_raw: roaCur, source: 'محسوب برمجيًا: صافي الربح ÷ إجمالي الأصول' });

// --- KPIs ---
const kpis = [];
function addKpi(icon, label, key) {
  const c = cur(key), p = prv(key);
  if (c == null) return;
  const b = toBillion(c);
  const ch = change(c, p);
  kpis.push({
    icon, label,
    value: b != null ? String(b) : String(c),
    unit: 'مليار ريال',
    change: ch != null ? (ch > 0 ? '+' : '') + ch + '%' : '',
    trend: trendOf(ch),
    source: 'مستخرج من القائمة'
  });
}
addKpi('💰', 'صافي الربح (Net Profit)', 'net_profit');
addKpi('📊', 'إجمالي الربح (Gross Profit)', 'gross_profit');
addKpi('⚙️', 'الربح التشغيلي (Operating Profit)', 'operating_profit');
addKpi('💵', 'الإيرادات (Revenue)', 'revenue');

// --- جدول الأرقام التفصيلية ---
const figLabels = {
  revenue: 'الإيرادات', cost_of_revenue: 'تكلفة الإيرادات', gross_profit: 'إجمالي الربح',
  operating_profit: 'الربح التشغيلي', net_profit: 'صافي الربح',
  total_assets: 'إجمالي الأصول', total_liabilities: 'إجمالي الخصوم', total_equity: 'حقوق الملكية',
  current_assets: 'الأصول المتداولة', current_liabilities: 'الخصوم المتداولة',
  cash: 'النقد وما في حكمه', operating_cf: 'التدفق النقدي التشغيلي'
};
const incomeKeys = ['revenue', 'cost_of_revenue', 'gross_profit', 'operating_profit', 'net_profit'];
const balanceKeys = ['total_assets', 'total_liabilities', 'total_equity', 'current_assets', 'current_liabilities', 'cash'];
function figRows(keys) {
  return keys.filter(k => cur(k) != null).map(k => ({
    label: figLabels[k] || k,
    current: String(toBillion(cur(k))),
    previous: prv(k) != null ? String(toBillion(prv(k))) : null,
    unit: 'مليار'
  }));
}
const figures = [];
const incRows = figRows(incomeKeys);
const balRows = figRows(balanceKeys);
if (incRows.length) figures.push({ category: 'قائمة الدخل', items: incRows });
if (balRows.length) figures.push({ category: 'المركز المالي', items: balRows });

// --- الرسوم البيانية ---
let growth_chart = null;
if (cur('revenue') != null && prv('revenue') != null) {
  growth_chart = { title: 'الإيرادات', unit: 'مليار', points: [
    { label: 'الفترة السابقة', value: toBillion(prv('revenue')) },
    { label: 'الفترة الحالية', value: toBillion(cur('revenue')) }
  ]};
}

let comparison_chart = null;
const cmpKeys = ['revenue', 'gross_profit', 'net_profit'].filter(k => cur(k) != null);
if (cmpKeys.length) {
  comparison_chart = {
    title: 'الفترة الحالية مقابل السابقة', unit: 'مليار',
    labels: cmpKeys.map(k => figLabels[k]),
    current: { name: 'الحالي', values: cmpKeys.map(k => toBillion(cur(k))) },
    previous: { name: 'السابق', values: cmpKeys.map(k => prv(k) != null ? toBillion(prv(k)) : null) }
  };
}

let composition_chart = null;
if (inp.segments && inp.segments.length >= 2) {
  composition_chart = { title: 'تركيبة القطاعات', items: inp.segments.map(s => ({ label: s.label, value: s.value })) };
}

// --- v17: ملخص التدفقات النقدية ---
let cashflow_summary = null;
{
  const op = cur('operating_cf'), inv = cur('investing_cf'), fin = cur('financing_cf'), capex = cur('capex');
  if (op != null || inv != null || fin != null) {
    let fcf = null;
    if (op != null && capex != null) fcf = op - Math.abs(capex);
    else if (op != null && inv != null) fcf = op + inv;
    cashflow_summary = {
      operating: op != null ? toBillion(op) : null,
      investing: inv != null ? toBillion(inv) : null,
      financing: fin != null ? toBillion(fin) : null,
      free_cash_flow: fcf != null ? toBillion(fcf) : null,
      unit: 'مليار'
    };
  }
}

// --- v17: ملخص حقوق المساهمين ---
let equity_summary = null;
{
  const te = cur('total_equity'), tePrev = prv('total_equity');
  const sc = cur('share_capital'), re = cur('retained_earnings');
  if (te != null) {
    equity_summary = {
      total_equity: toBillion(te),
      share_capital: sc != null ? toBillion(sc) : null,
      retained_earnings: re != null ? toBillion(re) : null,
      change_pct: change(te, tePrev),
      unit: 'مليار'
    };
  }
}

return [{
  json: {
    company: inp.company,
    period: inp.period,
    validation: inp.validation,
    computed: { kpis, ratios, figures, growth_chart, comparison_chart, composition_chart, cashflow_summary, equity_summary },
    meta: inp.meta
  }
}];

// ═══════════════════════════════════════════════════════════
// [5] Build Explain Request — بناء طلب الشرح للنموذج (v17)
// أضيف: تمرير cashflow_summary و equity_summary ضمن الحقائق
// ═══════════════════════════════════════════════════════════
const inp = $input.first().json;
const C = inp.computed;

const facts = {
  company: inp.company,
  period: inp.period,
  kpis: C.kpis.map(k => ({ label: k.label, value: k.value, unit: k.unit, change: k.change, trend: k.trend })),
  ratios: C.ratios.map(r => ({ label: r.label, value: r.value, previous: r.previous })),
  figures: C.figures,
  cashflow_summary: C.cashflow_summary || null,
  equity_summary: C.equity_summary || null,
  confidence: inp.validation.confidence
};

const prompt =
'أنت محرّر مالي. أُعطيت أرقامًا ونسبًا مُحسوبة مسبقًا وموثوقة. مهمتك صياغة شرح وصفي عربي حولها فقط.\n\n' +
'قواعد مُلزمة (صارمة جدًا):\n' +
'1- ممنوع منعًا باتًا إضافة أي رقم أو نسبة غير موجودة في البيانات المعطاة لك أدناه.\n' +
'2- ممنوع تعديل أو إعادة حساب أي رقم. استخدم الأرقام كما هي حرفيًا إذا ذكرتها.\n' +
'3- يمكنك الوصف الموضوعي فقط (ارتفع/انخفض/مستقر) استنادًا إلى الأرقام المعطاة.\n' +
'4- ممنوع أي توصية استثمارية (اشترِ/بِع/استثمر).\n' +
'5- إذا كانت درجة الثقة "low" أو "medium"، اذكر بوضوح أن الأرقام قد تكون غير مكتملة.\n' +
'6- لا تخترع اسم قطاع أو نشاط غير مذكور.\n' +
'7- إذا توفرت بيانات cashflow_summary أو equity_summary، يمكنك الإشارة إليها وصفيًا ضمن insight أو notes دون اختراع أرقام إضافية.\n\n' +
'البيانات المحسوبة (مصدر الحقيقة الوحيد):\n' +
JSON.stringify(facts, null, 1) +
'\n\nأرجع JSON بهذا الشكل بالضبط (نصوص وصفية فقط، بلا أرقام جديدة):\n' +
'{' +
'"summary":"جملتان تصفان أداء الشركة في الفترة استنادًا للأرقام أعلاه",' +
'"about":"وصف موجز للشركة والفترة المالية",' +
'"insight":"فقرة من 3 جمل تربط الأرقام المعطاة ببعضها وصفيًا",' +
'"ratio_notes":[{"label":"اسم النسبة كما ورد أعلاه","note":"تفسير وصفي بجملة واحدة"}],' +
'"risks":["ملاحظة وصفية أو مخاطرة محتملة مبنية على الأرقام المعطاة"],' +
'"notes":["حقيقة محايدة مذكورة بالأرقام المعطاة"]' +
'}';

const apiBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 2500,
  temperature: 0.2,
  messages: [
    { role: 'user', content: prompt },
    { role: 'assistant', content: '{' }
  ]
};

return [{
  json: {
    computed: C,
    validation: inp.validation,
    company: inp.company,
    period: inp.period,
    meta: inp.meta,
    api_body: JSON.stringify(apiBody)
  }
}];

// ═══════════════════════════════════════════════════════════
// [6] Assemble — دمج الأرقام المحسوبة مع الشرح النصي (v17)
// أضيف: إرسال cashflow_summary و equity_summary للواجهة
// ═══════════════════════════════════════════════════════════
const ai = $input.first().json;

const src = $('Build Explain Request').first().json;
const C = src.computed;
const V = src.validation;

let expl = {};
if (ai.content && Array.isArray(ai.content)) {
  let txt = ai.content.filter(b => b && b.type === 'text').map(b => b.text || '').join('');
  if (!txt.trim().startsWith('{')) txt = '{' + txt;
  txt = txt.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  try { expl = JSON.parse(txt); }
  catch (e) {
    const end = txt.lastIndexOf('}');
    if (end > 0) { try { expl = JSON.parse(txt.slice(0, end + 1)); } catch (e2) {} }
  }
}

const ratioNotes = {};
(expl.ratio_notes || []).forEach(r => { if (r && r.label) ratioNotes[r.label] = r.note; });
const ratios = C.ratios.map(r => ({
  label: r.label,
  value: r.value,
  previous: r.previous,
  note: ratioNotes[r.label] || ''
}));

const confLabel = { high: 'موثوقية عالية', medium: 'موثوقية متوسطة — راجع الأرقام', low: 'موثوقية منخفضة — تحقّق يدويًا' };
const disclaimerBase = 'عرض وصفي للأرقام المالية المعلنة دون توصية استثمارية. جميع الأرقام مستخرجة من القائمة أو محسوبة برمجيًا.';

const report = {
  summary: expl.summary || '',
  about: expl.about || '',
  insight: expl.insight || '',
  kpis: C.kpis,
  ratios,
  figures: C.figures,
  growth_chart: C.growth_chart || undefined,
  comparison_chart: C.comparison_chart || undefined,
  composition_chart: C.composition_chart || undefined,
  cashflow_summary: C.cashflow_summary || undefined,
  equity_summary: C.equity_summary || undefined,
  risks: Array.isArray(expl.risks) ? expl.risks : [],
  notes: Array.isArray(expl.notes) ? expl.notes : [],
  confidence: V.confidence,
  confidence_label: confLabel[V.confidence] || '',
  warnings: V.warnings || [],
  disclaimer: disclaimerBase
};

if (V.confidence === 'low') {
  report.summary = '⚠ تنبيه موثوقية: تعذّر التحقق الكامل من الأرقام، قد تكون ناقصة أو غير دقيقة. ' + report.summary;
}

return [{ json: { ok: true, report } }];

// ═══════════════════════════════════════════════════════════
// [2] Extract Numbers — استخراج الأرقام برمجياً من النص
// بدون AI — regex + pattern matching فقط
// ═══════════════════════════════════════════════════════════
const inp = $input.first().json;
const text = inp.clean_text || '';

// ─── تحويل الأرقام العربية للإنجليزية ───
function arabicToEn(s) {
  return String(s).replace(/[٠١٢٣٤٥٦٧٨٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
}

// ─── تنظيف رقم وتحويله لقيمة عددية ───
function parseNum(s) {
  if (!s) return null;
  s = arabicToEn(String(s)).replace(/,|،/g, '').replace(/\s/g, '').trim();
  // الأرقام بين قوسين = سالبة
  if (/^\([\d.]+\)$/.test(s)) s = '-' + s.replace(/[()]/g, '');
  const n = parseFloat(s);
  return isFinite(n) ? n : null;
}

// ─── البحث عن رقم بجانب كلمة مفتاحية ───
// يبحثفي السطر نفسه أو السطر التالي
function findValue(keywords, txt) {
  const lines = txt.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const matched = keywords.some(kw => line.includes(kw));
    if (!matched) continue;

    // البحث عن أرقام في نفس السطر
    const nums = arabicToEn(line).match(/\(?\d{1,3}(?:[,،٬]\d{3})+(?:\.\d+)?\)?|\(?\d+(?:\.\d+)?\)?/g);
    if (nums && nums.length > 0) {
      // نأخذ أول رقمين (current و previous)
      const current = parseNum(nums[0]);
      const previous = nums[1] ? parseNum(nums[1]) : null;
      if (current !== null) return { current, previous };
    }

    // البحث في السطر التالي
    if (i + 1 < lines.length) {
const nextNums = arabicToEn(lines[i + 1]).match(/\(?\d{1,3}(?:[,،٬]\d{3})+(?:\.\d+)?\)?|\(?\d+(?:\.\d+)?\)?/g);
        const current = parseNum(nextNums[0]);
        const previous = nextNums[1] ? parseNum(nextNums[1]) : null;
        if (current !== null) return { current, previous };
      }
    }
  }
  return { current: null, previous: null };

// ─── البحث عن الربح التشغيلي بدقة أعلى ───
// يتجاهل "صافي الربح قبل الزكاة" و"الربح الإجمالي"
function findOperatingProfit(txt) {
    const lines = txt.split('\n');
    for (let i = 0; i < lines.length; i++) {
          const line = lines[i];
          const isOperating = (
                  line.includes('الربح التشغيلي') ||
                  line.includes('ربح التشغيل') ||
                  line.toLowerCase().includes('operating profit') ||
                  line.toLowerCase().includes('profit from operations') ||
                      line.includes('ربح العمليات') ||
                      line.includes('دخل العمليات') ||
                      line.includes('صافي الدخل من العمليات') ||
                      line.includes('الربح قبل الزكاة والضريبة')
                );
          const isRatio = line.includes('هامش') || line.includes('نسبة') || line.includes('%');
          if (!isOperating || isRatio) continue;
                const nums = arabicToEn(line).match(/\(?\d{1,3}(?:[,،]\d{3})+(?:\.\d+)?\)?|\(?\d+(?:\.\d+)?\)?/g);
          if (nums && nums.length > 0) {
                  const current = parseNum(nums[0]);
                  const previous = nums[1] ? parseNum(nums[1]) : null;
                  if (current !== null) return { current, previous };
          }
          if (i + 1 < lines.length) {
                  const nextNums = arabicToEn(lines[i + 1]).match(/\(?\d{1,3}(?:[,،]\d{3})+(?:\.\d+)?\)?|\(?\d+(?:\.\d+)?\)?/g);
                  if (nextNums && nextNums.length > 0) {
                            const current = parseNum(nextNums[0]);
                            const previous = nextNums[1] ? parseNum(nextNums[1]) : null;
                            if (current !== null) return { current, previous };
                  }
          }
    }
    return { current: null, previous: null };
}

const extracted = {
    operating_profit:  findOperatingProfit(text),
    net_profit:        findValue(['صافي الربح','صافي الدخل','ربح الفترة','ربح الفتره','الربح الصافي','الدخل الصافي'], text),
    total_assets:      findValue(['إجمالي الأصول','اجمالي الاصول','مجموع الأصول','إجمالي الموجودات'], text),
    total_liabilities: findValue(['إجمالي الخصوم','اجمالي الخصوم','مجموع الخصوم','إجمالي المطلوبات'], text),
    total_equity:      findValue(['إجمالي حقوق الملكية','اجمالي حقوق الملكية','حقوق المساهمين','إجمالي حقوق المساهمين'], text),
    current_assets:    findValue(['الأصول المتداولة','اجمالي الاصول المتداولة','إجمالي الأصول المتداولة'], text),
    current_liabilities:findValue(['الخصوم المتداولة','اجمالي الخصوم المتداولة','إجمالي الخصوم المتداولة','الالتزامات المتداولة','إجمالي الالتزامات المتداولة'], text),
    cash:              findValue(['النقد وما في حكمه','النقد وما يعادله','نقد وما في حكمه'], text),
    share_capital:     findValue(['رأس المال','رأس المال المدفوع','رأس المال المصدر'], text),
    retained_earnings: findValue(['الأرباح المبقاة','الارباح المبقاة','الأرباح المحتجزة'], text),
    operating_cf:      findValue(['صافي النقد من الأنشطة التشغيلية','التدفق النقدي التشغيلي','صافي التدفقات النقدية من الأنشطة التشغيلية'], text),
    investing_cf:      findValue(['صافي النقد من الأنشطة الاستثمارية','التدفق النقدي الاستثماري','صافي التدفقات النقدية من الأنشطة الاستثمارية'], text),
    financing_cf:      findValue(['صافي النقد من الأنشطة التمويلية','التدفق النقدي التمويلي','صافي التدفقات النقدية من الأنشطة التمويلية'], text),
};

// ─── حساب عدد البنود المستخرجة ───
const extractedCount = Object.values(extracted).filter(v => v.current !== null).length;
const totalFields = Object.keys(extracted).length;

// ─── إذا الاستخراج البرمجي نجح بنسبة 60%+ نستخدمه، وإلا نتركه للـ AI ───
const isReliable = extractedCount >= Math.floor(totalFields * 0.6);

return [{
  json: {
    company: inp.company,
    period: inp.period,
    clean_text: inp.clean_text,
    scanned_images: inp.scanned_images,
    has_vision: inp.has_vision,
    meta: inp.meta,
    // الأرقام المستخرجة برمجياً
    programmatic_extraction: {
      data: extracted,
      extracted_count: extractedCount,
      total_fields: totalFields,
      is_reliable: isReliable
    }
  }
}];
